<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AuthShell from'../../Components/AuthShell.vue';import UiButton from'../../Components/UiButton.vue';defineProps({defaultCountryCode:String});const form=useForm({channel:'email',email:'',country_code:'+91',phone:''});</script><template><Head title="Create account"/><AuthShell eyebrow="Join LensPic" title="Create your secure workspace" description="Verify one contact method to continue."><div class="grid grid-cols-2 rounded-xl bg-slate-100 p-1" role="tablist"><button v-for="c in ['email','mobile']" :key="c" type="button" :aria-selected="form.channel===c" :class="['rounded-lg py-2.5 text-sm font-semibold capitalize',form.channel===c?'bg-white text-indigo shadow-sm':'text-slate-500 hover:text-ink']" @click="form.channel=c">{{c}}</button></div><form class="mt-6 space-y-5" @submit.prevent="form.post('/send-otp')"><label v-if="form.channel==='email'" class="lp-label">Email address<input v-model="form.email" type="email" autocomplete="email" class="field mt-2" required><span v-if="form.errors.email" class="lp-error">{{form.errors.email}}</span></label><div v-else class="grid grid-cols-[100px_1fr] gap-3"><label class="lp-label">Code<input v-model="form.country_code" class="field mt-2" autocomplete="tel-country-code"></label><label class="lp-label">Mobile<input v-model="form.phone" class="field mt-2" autocomplete="tel" required></label></div><UiButton type="submit" class="w-full" :loading="form.processing">Continue securely</UiButton><p class="text-center text-sm text-slate-600">Already registered? <Link href="/login" class="font-semibold text-indigo hover:underline">Sign in</Link></p></form></AuthShell></template>
